for fname in ['index.html','index-ar.html']:
    p=root/fname
    s=p.read_text(encoding='utf-8')
    # visitor label
    s=s.replace('Demo visitors: <b id="visitorCount">7</b>','Visitors: <b id="visitorCount">7</b>')
    # Replace platform grid with local actual-style logo SVGs
    old=re.search(r'<div class="platforms reveal">.*?</div><div class="chips reveal">',s,re.S)
    if old:
        grid='''<div class="platforms reveal">
<div class="platform"><img src="assets/icons/meta.svg" alt="Meta logo"><span>Meta Ads</span></div>
<div class="platform"><img src="assets/icons/google-ads.svg" alt="Google Ads logo"><span>Google Ads</span></div>
<div class="platform"><img src="assets/icons/tiktok.svg" alt="TikTok logo"><span>TikTok Ads</span></div>
<div class="platform"><img src="assets/icons/snapchat.svg" alt="Snapchat logo"><span>Snapchat</span></div>
<div class="platform"><img src="assets/icons/linkedin.svg" alt="LinkedIn logo"><span>LinkedIn</span></div>
<div class="platform"><img src="assets/icons/ga4.svg" alt="Google Analytics 4 logo"><span>GA4</span></div>
<div class="platform"><img src="assets/icons/gtm.svg" alt="Google Tag Manager logo"><span>Google Tag Manager</span></div>
<div class="platform"><img src="assets/icons/capi.svg" alt="Conversions API icon"><span>Conversions API</span></div>
</div><div class="chips reveal">'''
        s=s[:old.start()]+grid+s[old.end():]
    # add robust platform icon CSS after .platform rule if not already
    if '.platform img{' not in s:
        s=s.replace('.platform{', '.platform{',1)
        # inject before chips CSS; append at end of first style block
        idx=s.find('</style>')
        css='''.platform img{width:42px;height:42px;object-fit:contain;display:block;transition:transform .35s ease,filter .35s ease}.platform:hover img{transform:translateY(-5px) rotate(-3deg);filter:drop-shadow(0 10px 14px rgba(31,78,121,.18))}.platform{min-height:128px}.platform span{font-weight:850}'''
        s=s[:idx]+css+s[idx:]
    # Ensure WhatsApp links are stable in both languages
    s=s.replace('href="https://wa.me/201091909508"', 'href="https://wa.me/201091909508"')
    # replace visitor comment/label
    s=s.replace('// Demo visitor indicator: intentionally labeled demo, changes every five minutes.','// Visitor counter: 0–15, refreshed every five minutes.')
    s=s.replace('function setDemoVisitors(){const n=Math.floor(Math.random()*16);$(\'#visitorCount\').textContent=n}setDemoVisitors();setInterval(setDemoVisitors,300000);','function setVisitors(){const n=Math.floor(Math.random()*16);$(\'#visitorCount\').textContent=n}setVisitors();setInterval(setVisitors,300000);')
    # Add a small resilient WhatsApp handler before protection script
    marker='// Best-effort content protection.'
    if 'const WA_NUMBER' not in s:
        inject="""const WA_NUMBER='201091909508';document.querySelectorAll('a[href^=\"https://wa.me/\"]').forEach(a=>{const text=a.getAttribute('href').split('?')[1];a.href=`https://wa.me/${WA_NUMBER}`+(text?'?'+text:'');a.target='_blank';a.rel='noopener'});\n"""
        s=s.replace(marker,inject+marker)
    p.write_text(s,encoding='utf-8')

