import json
jsmap=json.dumps(translations,ensure_ascii=False,separators=(',',':'))
script=f'''<script>\ndocument.documentElement.lang='ar';document.documentElement.dir='rtl';document.body.classList.add('ar');\nconst AR={jsmap};\nfunction translateArabic(){{\n const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(n=>{{const t=n.nodeValue.trim();if(AR[t])n.nodeValue=n.nodeValue.replace(t,AR[t]);}});\n document.querySelectorAll('[placeholder]').forEach(el=>{{if(AR[el.placeholder])el.placeholder=AR[el.placeholder]}});document.querySelectorAll('[aria-label]').forEach(el=>{{if(AR[el.getAttribute('aria-label')])el.setAttribute('aria-label',AR[el.getAttribute('aria-label')])}});\n document.title='عمر عثمان | التسويق بالأداء وشراء الإعلانات';\n const brand=document.querySelector('.brand span:last-child');if(brand)brand.textContent='عمر عثمان';\n const lt=document.querySelector('#langTop'),fl=document.querySelector('#floatingLang');if(lt)lt.textContent='الإنجليزية';if(fl)fl.textContent='الإنجليزية';\n const sw=document.querySelector('#switchArabic');if(sw){{sw.textContent='الإنجليزية';sw.onclick=()=>location.href='index.html';}}\n const waTip=document.querySelector('.wa-tip');if(waTip)waTip.textContent='تواصل مع عمر';\n const wa=document.querySelector('.floating-wa');if(wa){{wa.href='https://wa.me/201091909508';wa.target='_blank';wa.rel='noopener';}}\n const searchBtn=document.querySelector('#searchBtn');if(searchBtn)searchBtn.setAttribute('aria-label','بحث');\n}}translateArabic();\n</script>\n</body></html>'''
s += script
ar.write_text(s,encoding='utf-8')

